// This file is generated by AI.

// 文件监听忽略判据的用例。
//
// 钉住的是一条**自激回路**: `git status` 每次都创建/删除 `.git/index.lock`, 而应用在项目根目录上
// 递归监听 → 监听到 `.git` 的变化 → 再 `git status` → 永不收敛。这里的用例保证判据不会退化。

import { describe, expect, it } from 'vitest';

import { hasRelevantWatchPath, isIgnoredWatchPath } from '../src/lib/watch-filter';

describe('isIgnoredWatchPath', () => {
  it('跳过版本控制元数据目录里的路径', () => {
    expect(isIgnoredWatchPath('C:\\proj\\.git\\index.lock')).toBe(true);
    expect(isIgnoredWatchPath('C:\\proj\\.git\\index')).toBe(true);
    expect(isIgnoredWatchPath('C:\\proj\\.git')).toBe(true);
    expect(isIgnoredWatchPath('/home/u/proj/.git/objects/ab/cdef')).toBe(true);
    expect(isIgnoredWatchPath('C:\\proj\\.hg\\store')).toBe(true);
    expect(isIgnoredWatchPath('C:\\proj\\.svn\\entries')).toBe(true);
  });

  it('大小写不敏感 (Windows 上 .GIT 与 .git 是同一个目录)', () => {
    expect(isIgnoredWatchPath('C:\\proj\\.GIT\\index')).toBe(true);
    expect(isIgnoredWatchPath('C:\\proj\\.Git\\HEAD')).toBe(true);
  });

  it('不误伤路径里含 "git" 的正常文件', () => {
    // 按分段判断而不是 includes('.git') —— 否则这些都会被错误地丢掉
    expect(isIgnoredWatchPath('C:\\proj\\game\\scene\\1.txt')).toBe(false);
    expect(isIgnoredWatchPath('C:\\proj\\game\\.gitkeep')).toBe(false);
    expect(isIgnoredWatchPath('C:\\proj\\scene\\git.txt')).toBe(false);
    expect(isIgnoredWatchPath('C:\\proj\\game\\legit\\file.txt')).toBe(false);
    // `.gitignore` 是正常文件: 默认 `.gitignore` 的内容由应用写入, 必须能被监听到
    expect(isIgnoredWatchPath('C:\\proj\\.gitignore')).toBe(false);
    expect(isIgnoredWatchPath('C:\\proj\\.gitattributes')).toBe(false);
  });

  it('空路径不算命中', () => {
    expect(isIgnoredWatchPath('')).toBe(false);
  });
});

describe('hasRelevantWatchPath', () => {
  it('整批都在 .git 里 → 不值得处理', () => {
    expect(hasRelevantWatchPath(['C:\\proj\\.git\\index.lock'])).toBe(false);
    expect(hasRelevantWatchPath(['C:\\proj\\.git\\index.lock', 'C:\\proj\\.git', 'C:\\proj\\.git\\index'])).toBe(false);
  });

  it('只要有一条正常路径就值得处理', () => {
    expect(hasRelevantWatchPath(['C:\\proj\\.git\\index', 'C:\\proj\\game\\scene\\1.txt'])).toBe(true);
    expect(hasRelevantWatchPath(['C:\\proj\\game\\config.txt'])).toBe(true);
  });

  it('拿不到路径时按值得处理算 (宁可多刷一次, 也别漏掉真实变更)', () => {
    expect(hasRelevantWatchPath(undefined)).toBe(true);
    expect(hasRelevantWatchPath(null)).toBe(true);
    expect(hasRelevantWatchPath([])).toBe(true);
  });
});
